"use client";

import { useEffect, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { Calendar } from "@/components/ui/calendar";
import {
	Collapsible,
	CollapsibleContent,
	CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
	eachMonthOfInterval,
	eachYearOfInterval,
	endOfYear,
	format,
	isAfter,
	isBefore,
	startOfYear,
} from "date-fns";
import { ChevronDownIcon } from "lucide-react";
import { CaptionLabelProps, MonthGridProps } from "react-day-picker";

export default function Component() {
	const today = new Date();
	const [month, setMonth] = useState(today);
	const [date, setDate] = useState<Date | undefined>(today);
	const [isYearView, setIsYearView] = useState(false);
	const startDate = new Date(1980, 6);
	const endDate = new Date(2030, 6);

	const years = eachYearOfInterval({
		start: startOfYear(startDate),
		end: endOfYear(endDate),
	});

	return (
		<div>
			<Calendar
				mode="single"
				selected={date}
				onSelect={setDate}
				month={month}
				onMonthChange={setMonth}
				defaultMonth={new Date()}
				startMonth={startDate}
				endMonth={endDate}
				className="overflow-hidden rounded-md border p-2"
				classNames={{
					month_caption: "ms-2.5 me-20 justify-start",
					nav: "justify-end",
				}}
				components={{
					CaptionLabel: (props: CaptionLabelProps) => (
						<CaptionLabel
							isYearView={isYearView}
							setIsYearView={setIsYearView}
							{...props}
						/>
					),
					MonthGrid: (props: MonthGridProps) => {
						return (
							<MonthGrid
								className={props.className}
								isYearView={isYearView}
								setIsYearView={setIsYearView}
								startDate={startDate}
								endDate={endDate}
								years={years}
								currentYear={month.getFullYear()}
								currentMonth={month.getMonth()}
								onMonthSelect={(selectedMonth: Date) => {
									setMonth(selectedMonth);
									setIsYearView(false);
								}}
							>
								{props.children}
							</MonthGrid>
						);
					},
				}}
			/>
			<p
				className="text-muted-foreground mt-4 text-center text-xs"
				role="region"
				aria-live="polite"
			>
				Advanced selection -{" "}
				<a
					className="hover:text-foreground underline"
					href="https://daypicker.dev/"
					target="_blank"
					rel="noopener nofollow"
				>
					React DayPicker
				</a>
			</p>
		</div>
	);
}

function MonthGrid({
	className,
	children,
	isYearView,
	startDate,
	endDate,
	years,
	currentYear,
	currentMonth,
	onMonthSelect,
}: {
	className?: string;
	children: React.ReactNode;
	isYearView: boolean;
	setIsYearView: React.Dispatch<React.SetStateAction<boolean>>;
	startDate: Date;
	endDate: Date;
	years: Date[];
	currentYear: number;
	currentMonth: number;
	onMonthSelect: (date: Date) => void;
}) {
	const currentYearRef = useRef<HTMLDivElement>(null);
	const currentMonthButtonRef = useRef<HTMLButtonElement>(null);
	const scrollAreaRef = useRef<HTMLDivElement>(null);

	useEffect(() => {
		if (isYearView && currentYearRef.current && scrollAreaRef.current) {
			const viewport = scrollAreaRef.current.querySelector(
				"[data-radix-scroll-area-viewport]"
			) as HTMLElement;
			if (viewport) {
				const yearTop = currentYearRef.current.offsetTop;
				viewport.scrollTop = yearTop;
			}
			setTimeout(() => {
				currentMonthButtonRef.current?.focus();
			}, 100);
		}
	}, [isYearView]);

	return (
		<div className="relative">
			<table className={className}>{children}</table>
			{isYearView && (
				<div className="bg-background absolute inset-0 z-20 -mx-2 -mb-2">
					<ScrollArea ref={scrollAreaRef} className="h-full">
						{years.map((year) => {
							const months = eachMonthOfInterval({
								start: startOfYear(year),
								end: endOfYear(year),
							});
							const isCurrentYear = year.getFullYear() === currentYear;

							return (
								<div
									key={year.getFullYear()}
									ref={isCurrentYear ? currentYearRef : undefined}
								>
									<CollapsibleYear
										title={year.getFullYear().toString()}
										open={isCurrentYear}
									>
										<div className="grid grid-cols-3 gap-2">
											{months.map((month) => {
												const isDisabled =
													isBefore(month, startDate) ||
													isAfter(month, endDate);
												const isCurrentMonth =
													month.getMonth() === currentMonth &&
													year.getFullYear() === currentYear;

												return (
													<Button
														key={month.getTime()}
														ref={
															isCurrentMonth
																? currentMonthButtonRef
																: undefined
														}
														variant={
															isCurrentMonth
																? "default"
																: "outline"
														}
														size="sm"
														className="h-7"
														disabled={isDisabled}
														onClick={() => onMonthSelect(month)}
													>
														{format(month, "MMM")}
													</Button>
												);
											})}
										</div>
									</CollapsibleYear>
								</div>
							);
						})}
					</ScrollArea>
				</div>
			)}
		</div>
	);
}

function CaptionLabel({
	children,
	isYearView,
	setIsYearView,
}: {
	isYearView: boolean;
	setIsYearView: React.Dispatch<React.SetStateAction<boolean>>;
} & React.HTMLAttributes<HTMLSpanElement>) {
	return (
		<Button
			className="data-[state=open]:text-muted-foreground/80 -ms-2 flex items-center gap-2 text-sm font-medium hover:bg-transparent [&[data-state=open]>svg]:rotate-180"
			variant="ghost"
			size="sm"
			onClick={() => setIsYearView((prev) => !prev)}
			data-state={isYearView ? "open" : "closed"}
		>
			{children}
			<ChevronDownIcon
				size={16}
				className="text-muted-foreground/80 shrink-0 transition-transform duration-200"
				aria-hidden="true"
			/>
		</Button>
	);
}

function CollapsibleYear({
	title,
	children,
	open,
}: {
	title: string;
	children: React.ReactNode;
	open?: boolean;
}) {
	return (
		<Collapsible className="border-t px-2 py-1.5" defaultOpen={open}>
			<CollapsibleTrigger asChild>
				<Button
					className="flex w-full justify-start gap-2 text-sm font-medium hover:bg-transparent [&[data-state=open]>svg]:rotate-180"
					variant="ghost"
					size="sm"
				>
					<ChevronDownIcon
						size={16}
						className="text-muted-foreground/80 shrink-0 transition-transform duration-200"
						aria-hidden="true"
					/>
					{title}
				</Button>
			</CollapsibleTrigger>
			<CollapsibleContent className="data-[state=closed]:animate-collapsible-up data-[state=open]:animate-collapsible-down overflow-hidden px-3 py-1 text-sm transition-all">
				{children}
			</CollapsibleContent>
		</Collapsible>
	);
}

import * as React from "react";

import { cn } from "@/registry/utilities/cn";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

"use client";

import React from "react";

import { cn } from "@/registry/utilities/cn";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { DayPicker } from "react-day-picker";

import { buttonVariants } from "./button";

export type CalendarProps = React.ComponentProps<typeof DayPicker>;

function Calendar({
	className,
	classNames,
	showOutsideDays = true,
	...props
}: CalendarProps) {
	return (
		<DayPicker
			showOutsideDays={showOutsideDays}
			className={cn("p-3", className)}
			classNames={{
				months:
					"flex flex-col sm:flex-row space-y-4 sm:space-x-4 sm:space-y-0",
				month: "space-y-4",
				caption: "flex justify-center pt-1 relative items-center",
				caption_label: "text-sm font-medium",
				nav: "space-x-1 flex items-center",
				nav_button: cn(
					buttonVariants({ variant: "outline" }),
					"h-7 w-7 bg-transparent p-0 opacity-50 hover:opacity-100"
				),
				nav_button_previous: "absolute left-1",
				nav_button_next: "absolute right-1",
				table: "w-full border-collapse space-y-1",
				head_row: "flex",
				head_cell:
					"text-muted-foreground rounded-md w-9 font-normal text-[0.8rem]",
				row: "flex w-full mt-2",
				cell: "h-9 w-9 text-center text-sm p-0 relative [&:has([aria-selected].day-range-end)]:rounded-r-md [&:has([aria-selected].day-outside)]:bg-accent/50 [&:has([aria-selected])]:bg-accent first:[&:has([aria-selected])]:rounded-l-md last:[&:has([aria-selected])]:rounded-r-md focus-within:relative focus-within:z-20",
				day: cn(
					buttonVariants({ variant: "ghost" }),
					"h-9 w-9 p-0 font-normal aria-selected:opacity-100"
				),
				day_range_end: "day-range-end",
				day_selected:
					"bg-primary text-primary-foreground hover:bg-primary hover:text-primary-foreground focus:bg-primary focus:text-primary-foreground",
				day_today: "bg-accent text-accent-foreground",
				day_outside:
					"day-outside text-muted-foreground opacity-50 aria-selected:bg-accent/50 aria-selected:text-muted-foreground aria-selected:opacity-30",
				day_disabled: "text-muted-foreground opacity-50",
				day_range_middle:
					"aria-selected:bg-accent aria-selected:text-accent-foreground",
				day_hidden: "invisible",
				...classNames,
			}}
			components={{
				IconLeft: ({ ...props }) => <ChevronLeft className="h-4 w-4" />,
				IconRight: ({ ...props }) => <ChevronRight className="h-4 w-4" />,
			}}
			{...props}
		/>
	);
}
Calendar.displayName = "Calendar";

export { Calendar };

"use client";

import React from "react";

import { cn } from "@/registry/utilities/cn";
import * as ScrollAreaPrimitive from "@radix-ui/react-scroll-area";

const ScrollArea = React.forwardRef<
	React.ElementRef<typeof ScrollAreaPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof ScrollAreaPrimitive.Root>
>(({ className, children, ...props }, ref) => (
	<ScrollAreaPrimitive.Root
		ref={ref}
		className={cn("relative overflow-hidden", className)}
		{...props}
	>
		<ScrollAreaPrimitive.Viewport className="h-full w-full rounded-[inherit]">
			{children}
		</ScrollAreaPrimitive.Viewport>
		<ScrollBar />
		<ScrollAreaPrimitive.Corner />
	</ScrollAreaPrimitive.Root>
));
ScrollArea.displayName = ScrollAreaPrimitive.Root.displayName;

const ScrollBar = React.forwardRef<
	React.ElementRef<typeof ScrollAreaPrimitive.ScrollAreaScrollbar>,
	React.ComponentPropsWithoutRef<
		typeof ScrollAreaPrimitive.ScrollAreaScrollbar
	>
>(({ className, orientation = "vertical", ...props }, ref) => (
	<ScrollAreaPrimitive.ScrollAreaScrollbar
		ref={ref}
		orientation={orientation}
		className={cn(
			"flex touch-none select-none transition-colors",
			orientation === "vertical" &&
				"h-full w-2.5 border-l border-l-transparent p-[1px]",
			orientation === "horizontal" &&
				"h-2.5 flex-col border-t border-t-transparent p-[1px]",
			className
		)}
		{...props}
	>
		<ScrollAreaPrimitive.ScrollAreaThumb className="relative flex-1 rounded-full bg-border" />
	</ScrollAreaPrimitive.ScrollAreaScrollbar>
));
ScrollBar.displayName = ScrollAreaPrimitive.ScrollAreaScrollbar.displayName;

export { ScrollArea, ScrollBar };
